"kind": "propose",
"summary": "Adjust probe timeouts for new revision to accommodate startup delays",
"hypotheses": [
    {
        "root_cause_class": "probe_too_strict_for_startup",
        "summary": "Liveness probe failed during startup due to timeout",
        "supporting": ["ev-target_events", "ev-pod_states", "ev-rollout_history"],
        "contradicting": [],
        "missing": ["container_logs_tail"],
        "status": "supported"
    },
    {
        "root_cause_class": "new_version_broken",
        "summary": "New revision's probes fail before app is ready",
        "supporting": ["ev-target_events", "ev-pod_states"],
        "contradicting": ["prior_revision_was_healthy"],
        "missing": [],
        "status": "supported"
    }
],
"proposal": {
    "capability": "deployment.set-probes",
    "target": {
        "group": "apps",
        "kind": "Deployment",
        "namespace": "edge",
        "name": "api-gateway",
        "uid": "uid-deployment-api-gateway"
    },
    "params": {
        "container": "app",
        "liveness": {
            "timeoutSeconds": 5
        },
        "readiness": {
            "timeoutSeconds": 5
        }
    },
    "expected_effect": "Allow application to complete startup before probe timeouts",
    "rationale": "The pod took 1m2s to start but liveness/readiness probes timed out at 1s, causing restarts. Increasing timeouts to 5s matches the observed startup duration from pod_states and events.",
    "cited_evidence_ids": ["ev-target_events", "ev-pod_states", "ev-rollout_history"],
    "cited_predicates": ["killed_during_startup", "probe_kills", "probe_timeouts"]
}
}
